INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Savezna Republika Jugoslavija', 'sr-Latn', NULL, NULL, 'Serbian Latin-script romanization of the constitutional name', 'en.wikipedia.org/wiki/Serbia_and_Montenegro');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Federal Republic of Yugoslavia', 'en', NULL, NULL, 'Standard English designation (FRY) used by the UN, ICTY and Western governments 1992–2003', 'ICTY, icty.org/en/about/what-former-yugoslavia');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Savezna Republika Jugoslavija (Савезна Република Југославија)', 'hbs', NULL, NULL, 'Same name in the shared Serbo-Croatian/Bosnian standard used across the former Yugoslavia', 'Wikidata Q37024');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Трећа Југославија (Treća Jugoslavija)', 'sr', NULL, NULL, 'Denominazione informale ''Terza Jugoslavia'' (dopo il Regno e la SFRJ); lang sr.', 'Britannica, britannica.com/place/Yugoslavia-former-federated-nation-1929-2003');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 1992, 'Serbia and Montenegro', 'FOUNDING', 'On 27 April 1992 the Assembly in Belgrade adopted the FRY constitution, constituting a two-republic federation (Serbia incl. the autonomous provinces of Kosovo and Vojvodina, plus Montenegro) as the self-declared continuation of SFR Yugoslavia. The UN Security Council (Res. 777/1992) rejected automatic continuity and required reapplication for membership.', 10394026, 0.92);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 1992, 'International / Bosnia-Herzegovina', 'REFORM', 'UN Security Council Resolution 757 (30 May 1992) imposed a near-total trade embargo, financial and air-traffic sanctions on the FRY for Belgrade''s role in arming and directing Bosnian Serb forces during the Bosnian War; sanctions crippled the economy through the 1990s.', NULL, 0.92);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 1999, 'Kosovo', 'OCCUPATION', 'During the Kosovo War, Yugoslav/Serbian forces under Milošević forcibly expelled roughly 863,000 Kosovo Albanians (Mar–Jun 1999); NATO''s Operation Allied Force bombed the FRY 24 Mar–9 Jun 1999, after which UNSC Res. 1244 placed Kosovo under UN administration (UNMIK/KFOR), removing it from effective Belgrade control.', 863000, 0.92);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 2003, 'Serbia and Montenegro', 'REFORM', 'On 4 February 2003 the Federal Assembly promulgated the Constitutional Charter, abolishing the name ''Federal Republic of Yugoslavia'' and reconstituting the polity as the looser State Union of Serbia and Montenegro, ending the Yugoslav state name after 74 years.', NULL, 0.92);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'International Criminal Tribunal for the former Yugoslavia (ICTY), "What is the former Yugoslavia?" — official background on the SFRY/FRY and the wars of the 1990s.', 'https://www.icty.org/en/about/what-former-yugoslavia', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'United Nations Security Council Resolution 757 (S/RES/757, 30 May 1992), imposing comprehensive sanctions on the Federal Republic of Yugoslavia (Serbia and Montenegro).', 'https://digitallibrary.un.org/record/142881', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Human Rights Watch, "Under Orders: War Crimes in Kosovo" (2001) — documentation of forced expulsions and killings by Serbian/Yugoslav forces and of civilian deaths from NATO bombing.', 'https://www.hrw.org/reports/2001/kosovo/', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Spiegel PB & Salama P, "War and mortality in Kosovo, 1998–99: an epidemiological testimony," The Lancet 355 (2000): 2204–2209 — CDC-linked mortality estimate (~12,000 war-related deaths).', 'https://www.thelancet.com/pdfs/journals/lancet/PIIS0140673600024041.pdf', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 'Encyclopaedia Britannica, "Yugoslavia (former federated nation, 1929–2003)" and "Serbia and Montenegro" — standard reference for the 27 April 1992 founding, 4 February 2003 renaming, and Belgrade capital.', 'https://www.britannica.com/place/Yugoslavia-former-federated-nation-1929-2003', 'secondary');
