INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 'Serbia and Montenegro', 'en', NULL, NULL, 'Standard English name of the state union (2003-2006)', 'en.wikipedia.org/wiki/Serbia_and_Montenegro');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 'Crna Gora', 'cnr', NULL, NULL, 'Montenegrin form of the co-constituent republic''s name; Montenegrin is now recognized as a distinct standard', 'en.wikipedia.org/wiki/Constitutional_Charter_of_Serbia_and_Montenegro');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 2002, 'Serbia and Montenegro', 'REFORM', 'Belgrade Agreement (Accord on Principles in Relations between Serbia and Montenegro), signed March 2002 by the Serbian, Montenegrin and FRY governments under EU mediation (Javier Solana), framing the restructuring of the FRY into a loose state union.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 2003, 'Federal Republic of Yugoslavia / Serbia and Montenegro', 'REFORM', 'Constitutional Charter came into force 4 February 2003, transforming the Federal Republic of Yugoslavia into the confederal State Union of Serbia and Montenegro and retiring the name ''Yugoslavia''.', 10825900, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 2006, 'Montenegro', 'SECESSION', 'Montenegrin independence referendum of 21 May 2006 (55.5% in favour, EU/Venice Commission threshold 55%); Montenegro''s parliament declared independence 3 June 2006, ending the union.', 620000, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 2006, 'Serbia and Montenegro', 'DISSOLUTION', 'Serbia''s parliament declared Serbia the legal successor to the State Union on 5 June 2006, dissolving Serbia and Montenegro into two independent states.', 10832545, 0.9);
