  ((SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 'Constitutional Charter of the State Union of Serbia and Montenegro, adopted by the Federal Assembly, 4 February 2003.', 'https://www.worldstatesmen.org/SerbMont_Const_2003.pdf', 'primary');
