INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 2006, 'Montenegro', 'SECESSION', 'Following the referendum of 21 May 2006 (55.5% in favour), Montenegro declared independence on 3 June 2006. On 5 June 2006 the National Assembly of Serbia declared the Republic of Serbia the legal successor of the State Union, formally dissolving Serbia and Montenegro. The separation was peaceful and referendum-based, brokered under EU mediation (Javier Solana''s threshold of 55%).', 620000, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 2006, 'Serbia', 'FOUNDING', 'Re-emergence of Serbia as a fully sovereign independent state for the first time since 1918. A new constitution — the first as an independent state since the Kingdom of Serbia''s 1903 constitution — was adopted by referendum on 28-29 October 2006 and promulgated on 8 November 2006.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 2008, 'Kosovo', 'SECESSION', 'Kosovo''s Assembly issued a unilateral declaration of independence on 17 February 2008, which Serbia rejects as illegitimate; the Serbian constitution continues to claim Kosovo and Metohija as an inalienable part of Serbia. The ICJ advisory opinion of 22 July 2010 found the declaration did not violate international law. De facto Serbian administrative control was lost after the 1998-1999 war and the NATO bombing of the Federal Republic of Yugoslavia (Milošević era); status remains disputed.', 1800000, 0.9);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 'Constitution of the Republic of Serbia (Ustav Republike Srbije), adopted 8 November 2006, Official Gazette RS No. 98/2006 — see Preamble and Article 10 on Kosovo and Metohija and official languages/script.', 'https://www.wipo.int/wipolex/en/legislation/details/7378', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 'International Court of Justice, ''Accordance with International Law of the Unilateral Declaration of Independence in Respect of Kosovo'', Advisory Opinion of 22 July 2010, ICJ Reports 2010, p. 403.', 'https://www.icj-cij.org/case/141', 'primary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 'Sabrina P. Ramet, ''The Three Yugoslavias: State-Building and Legitimation, 1918-2005'', Indiana University Press, 2006.', NULL, 'academic');
