-- v6.99.130 (Task 2c / ETHICS-025) — Serbia moderna: FRY + S&M + Republic of Serbia + catena 34.
-- Backup PRIMA. ON_ERROR_STOP=1. Confini approximate_generated.
BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM geo_entities WHERE name_original IN ('Савезна Република Југославија', 'Државна заједница Србија и Црна Гора', 'Република Србија')) THEN
    RAISE EXCEPTION 'entità Serbia moderna già presenti'; END IF;
END $$;

