VALUES ('Државна заједница Србија и Црна Гора', 'sr-Cyrl', 'federation', 2003, 2006,
  'Belgrade', 44.8125, 20.4612, '{"type": "Polygon", "coordinates": [[[22.5187, 44.8125], [23.0018, 45.7921], [21.837, 46.2527], [20.4612, 46.6559], [18.8049, 46.6558], [18.8399, 45.6351], [17.5618, 44.8125], [18.4593, 43.9037], [19.4331, 43.5373], [20.4612, 43.0713], [21.6589, 43.4056], [22.9163, 43.8102], [22.5187, 44.8125]]]}', 'approximate_generated',
  0.9, 'confirmed', 'Il quesito dell''unione tra Serbia e Montenegro ammette due letture storiografiche che il record non arbitra (ETHICS-003). Lettura pro-indipendenza: l''unione statale del 2003 fu un contenitore lasco mediato dall''Occidente (in particolare dall''inviato UE Javier Solana, da cui il soprannome ''Solania'') per rinviare la separazione, e il referendum del 21 maggio 2006 completò l''autodeterminazione montenegrina. Lettura pro-unionista/serba: la soglia del 55% fissata dall''UE fu imposta dall''esterno e l''esito (55,5%) fu talmente stretto da restare contestato. Entrambe vanno registrate con attribuzione. Va inoltre esplicitato che durante tutta l''esistenza dell''unione il Kosovo restò de iure parte della Serbia ma sotto amministrazione ONU (UNMIK) in base alla Risoluzione 1244 del Consiglio di Sicurezza (1999), conseguenza dei bombardamenti NATO e del conflitto del 1998-99; questo status irrisolto non è edulcorato ma non altera i confini nominali dell''entità.', 'Q37024',
  ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon", "coordinates": [[[22.5187, 44.8125], [23.0018, 45.7921], [21.837, 46.2527], [20.4612, 46.6559], [18.8049, 46.6558], [18.8399, 45.6351], [17.5618, 44.8125], [18.4593, 43.9037], [19.4331, 43.5373], [20.4612, 43.0713], [21.6589, 43.4056], [22.9163, 43.8102], [22.5187, 44.8125]]]}')));

-- ── Република Србија ──
  capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
  confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('Република Србија', 'sr-Cyrl', 'republic', 2006, NULL,
  'Belgrade', 44.8125, 20.4612, '{"type": "Polygon", "coordinates": [[[23.1963, 44.8125], [22.4063, 45.5786], [21.4743, 46.1761], [20.4612, 46.4925], [19.7218, 45.9085], [19.2384, 45.2973], [18.7777, 44.8125], [18.5749, 44.0369], [19.3521, 43.5214], [20.4612, 43.0456], [21.7403, 43.3673], [22.16, 44.1051], [23.1963, 44.8125]]]}', 'approximate_generated',
  0.9, 'confirmed', 'Il conflitto del Kosovo del 1998-1999 va nominato per primo (ETHICS-002): le forze serbo-jugoslave dell''era di Slobodan Milošević condussero una pulizia etnica su larga scala (circa 850.000 albanesi kosovari espulsi e migliaia di uccisi), che innescò l''intervento aereo NATO (marzo-giugno 1999) e l''amministrazione ONU del Kosovo (UNMIK, Ris. CdS 1244). Su questo sfondo si colloca la disputa successiva sullo status. Il record documenta senza arbitrare la disputa sul Kosovo, il territorio più contestato dello Stato. Lettura serba: la Costituzione del 2006 sancisce nel preambolo il Kosovo e Metohija come parte integrante e inalienabile della Serbia; Belgrado considera la dichiarazione unilaterale d''indipendenza del Kosovo (17 febbraio 2008) illegittima e non la riconosce. Lettura kosovara/di parte della comunità internazionale: il Kosovo esercita controllo statale de facto e il parere consultivo della Corte Internazionale di Giustizia del 22 luglio 2010 stabilì (10 voti contro 4) che la dichiarazione non violava il diritto internazionale; il numero di Stati riconoscenti è a sua volta conteso (il Kosovo rivendica ~120 riconoscimenti, la Serbia ne conta ~84-85 dopo la propria campagna di de-riconoscimento avviata dal 2017-2020). Entrambe le letture sono registrate senza risoluzione. La secessione del Montenegro (2006) fu pacifica e frutto di referendum, non di violenza.', 'Q403',
  ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon", "coordinates": [[[23.1963, 44.8125], [22.4063, 45.5786], [21.4743, 46.1761], [20.4612, 46.4925], [19.7218, 45.9085], [19.2384, 45.2973], [18.7777, 44.8125], [18.5749, 44.0369], [19.3521, 43.5214], [20.4612, 43.0456], [21.7403, 43.3673], [22.16, 44.1051], [23.1963, 44.8125]]]}')));

-- ── catena 34: +3 link (seq 7..9) ──
VALUES (34, (SELECT id FROM geo_entities WHERE name_original = 'Савезна Република Југославија'), 7, 1992, 'DISSOLUTION', true, 'As the SFR Yugoslavia broke up in the 1991-1995 wars (Slovenia, Croatia, Bosnia, Macedonia seceding), Serbia and Montenegro proclaimed the Federal Republic of Yugoslavia on 27 April 1992 as the rump/claimed-continuator state.', 'is_violent=true: the FRY was born from the violent dissolution of the SFRY (Yugoslav wars, including the Srebrenica genocide of 1995 by Bosnian Serb forces, and the 1998-99 Kosovo war and NATO intervention involving FRY forces). Milošević-era Serbia was a principal party; perpetrator roles are named on the relevant entities.');
VALUES (34, (SELECT id FROM geo_entities WHERE name_original = 'Државна заједница Србија и Црна Гора'), 8, 2003, 'REFORM', false, 'The Constitutional Charter of 4 February 2003 restructured the FRY into the loose State Union of Serbia and Montenegro, retiring the name ''Yugoslavia'' after 74 years (EU-mediated, the ''Solania'' arrangement).', 'A constitutional restructuring/renaming, not a violent transition. Kosovo remained de iure part of Serbia but under UN administration (UNMIK, UNSC Res 1244).');
VALUES (34, (SELECT id FROM geo_entities WHERE name_original = 'Република Србија'), 9, 2006, 'SECESSION', false, 'Montenegro''s independence referendum of 21 May 2006 (55.5% vs the EU-set 55% threshold) led to Montenegro''s declaration of independence on 3 June 2006; Serbia''s National Assembly declared the Republic of Serbia the successor state on 5 June 2006.', 'Peaceful secession by referendum. Both historiographies on the 55% threshold and the union are recorded on the Serbia-and-Montenegro entity; the unresolved Kosovo dispute (2008 UDI) is recorded on the Republic of Serbia entity, not arbitrated.');
UPDATE dynasty_chains SET name='Serbian state trunk: Raska → Srpsko Carstvo → Српска деспотовина → Ottoman → Кнежевина Србија → Југославија (СХС → СФРЈ → СРЈ → СЦГ) → Република Србија' WHERE id=34;

DO $$ DECLARE n int; bad int;
BEGIN
  SELECT count(*) INTO n FROM geo_entities WHERE name_original IN ('Савезна Република Југославија', 'Државна заједница Србија и Црна Гора', 'Република Србија');
  IF n <> 3 THEN RAISE EXCEPTION 'attese 3 entità, trovate %', n; END IF;
  SELECT count(*) INTO bad FROM (SELECT chain_id FROM chain_links WHERE chain_id=34 GROUP BY chain_id HAVING count(*)<>max(sequence_order)+1 OR min(sequence_order)<>0) t;
  IF bad<>0 THEN RAISE EXCEPTION 'catena 34 sequence non contigua'; END IF;
  SELECT count(*) INTO bad FROM geo_entities WHERE name_original IN ('Савезна Република Југославија', 'Државна заједница Србија и Црна Гора', 'Република Србија') AND (ST_XMax(boundary_geom)-ST_XMin(boundary_geom))>=180;
  IF bad<>0 THEN RAISE EXCEPTION '% confini antimeridiano', bad; END IF;
  -- ETHICS-003: nessun disputed sopra 0.70 tra i nuovi
  SELECT count(*) INTO bad FROM geo_entities WHERE name_original IN ('Савезна Република Југославија', 'Државна заједница Србија и Црна Гора', 'Република Србија') AND status='disputed' AND confidence_score>0.70;
  IF bad<>0 THEN RAISE EXCEPTION '% disputed sopra cap 0.70', bad; END IF;
  RAISE NOTICE 'Task 2c OK: FRY + S&M + Republic of Serbia + catena 34 (10 link)';
END $$;
COMMIT;
